-- Run in Supabase SQL Editor. All user-owned records are protected by RLS.
create extension if not exists pgcrypto;
create table public.profiles(user_id uuid primary key references auth.users(id) on delete cascade,display_name text default '',locale text not null default 'he' check(locale in ('he','en')),currency text not null default 'ILS',created_at timestamptz default now());
create table public.workplaces(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null check(length(name) between 1 and 100),hourly_rate numeric(12,2) not null default 43 check(hourly_rate>=0),overtime_after_hours numeric(5,2) not null default 8 check(overtime_after_hours>0),overtime_multiplier numeric(5,2) not null default 1.25 check(overtime_multiplier>=1),weekend_multiplier numeric(5,2) not null default 1 check(weekend_multiplier>=1),created_at timestamptz default now());
create table public.shifts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,workplace_id uuid not null references public.workplaces(id) on delete cascade,started_at timestamptz not null,ended_at timestamptz not null,unpaid_break_minutes integer not null default 0 check(unpaid_break_minutes>=0),gross_estimate numeric(12,2) not null check(gross_estimate>=0),created_at timestamptz default now(),check(ended_at>started_at));
create table public.transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,kind text not null check(kind in ('income','expense')),amount numeric(12,2) not null check(amount>0),category text not null default 'other',note text not null default '',occurred_on date not null default current_date,created_at timestamptz default now());
create table public.goals(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null check(length(title) between 1 and 120),target_amount numeric(12,2) not null check(target_amount>0),starting_savings numeric(12,2) not null default 0 check(starting_savings>=0),target_date date,created_at timestamptz default now());
create table public.contributions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,goal_id uuid not null references public.goals(id) on delete cascade,amount numeric(12,2) not null check(amount>0),contributed_on date not null default current_date);
create table public.budgets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,category text not null,monthly_limit numeric(12,2) not null check(monthly_limit>=0),unique(user_id,category));
create table public.recurring_transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,kind text not null check(kind in ('income','expense')),amount numeric(12,2) not null check(amount>0),category text not null,description text not null default '',day_of_month integer not null check(day_of_month between 1 and 28),active boolean not null default true);
create table public.reminders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,due_on date not null,done boolean not null default false);
create or replace function public.check_child_owner() returns trigger language plpgsql set search_path=public as $$ begin if tg_table_name='shifts' and not exists(select 1 from public.workplaces where id=new.workplace_id and user_id=new.user_id) then raise exception 'Workplace owner mismatch'; end if; if tg_table_name='contributions' and not exists(select 1 from public.goals where id=new.goal_id and user_id=new.user_id) then raise exception 'Goal owner mismatch'; end if; return new; end $$;
create trigger shifts_owner before insert or update on public.shifts for each row execute function public.check_child_owner();
create trigger contributions_owner before insert or update on public.contributions for each row execute function public.check_child_owner();
create or replace function public.make_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(user_id) values(new.id) on conflict do nothing;return new;end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.make_profile();
-- Profile self-management and user-owned table policies
alter table public.profiles enable row level security;
create policy profile_select on public.profiles for select to authenticated using(user_id=(select auth.uid()));
create policy profile_insert on public.profiles for insert to authenticated with check(user_id=(select auth.uid()));
create policy profile_update on public.profiles for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy profile_delete on public.profiles for delete to authenticated using(user_id=(select auth.uid()));
do $$ declare t text; begin foreach t in array array['workplaces','shifts','transactions','goals','contributions','budgets','recurring_transactions','reminders'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy owner_select on public.%I for select to authenticated using (user_id=(select auth.uid()))',t);execute format('create policy owner_insert on public.%I for insert to authenticated with check (user_id=(select auth.uid()))',t);execute format('create policy owner_update on public.%I for update to authenticated using (user_id=(select auth.uid())) with check (user_id=(select auth.uid()))',t);execute format('create policy owner_delete on public.%I for delete to authenticated using (user_id=(select auth.uid()))',t);end loop;end $$;
-- Authenticated users may delete their own account via a narrowly scoped function.
create or replace function public.delete_my_account() returns void language plpgsql security definer set search_path=public,auth as $$ begin if auth.uid() is null then raise exception 'Authentication required';end if;delete from auth.users where id=auth.uid();end $$;
revoke all on function public.delete_my_account() from public;
grant execute on function public.delete_my_account() to authenticated;
